"""Voice metric instruments: declarative specs and registration.

Each instrument is fully described by one
:class:`~rasa.tracing.shared.instrument_spec.InstrumentSpec` in
``VOICE_INSTRUMENT_SPECS`` — name, kind, unit, description, attribute
allowlist, and histogram buckets. The SDK Views and the registered
instruments are both derived from that single source of truth, so the
allowlist enforced at export time can never drift from the declaration.

Instruments exist only after :func:`register_voice_metric_instruments` runs
(invoked from ``rasa.tracing.metrics_config.configure_metrics``); until then
lookups return ``None`` and the recording functions stay no-ops.
"""

from __future__ import annotations

from typing import List, Optional, Tuple, Union

from opentelemetry.metrics import Counter, Histogram
from opentelemetry.sdk.metrics.view import View

from rasa.tracing.shared import instrument_registry
from rasa.tracing.shared.instrument_spec import InstrumentKind, InstrumentSpec
from rasa.tracing.voice.shared import semconv

# ---------------------------------------------------------------------------
# Histogram buckets (seconds)
# ---------------------------------------------------------------------------

# Calls range from a few seconds (immediate hangup) to hour-long sessions.
CALL_DURATION_BUCKET_BOUNDARIES_S = (
    5.0,
    15.0,
    30.0,
    60.0,
    120.0,
    300.0,
    600.0,
    1200.0,
    1800.0,
    2700.0,
    3600.0,
)

# TTS spans sub-10 ms cache hits to provider timeouts of tens of seconds.
TTS_DURATION_BUCKET_BOUNDARIES_S = (
    0.005,
    0.01,
    0.025,
    0.05,
    0.1,
    0.25,
    0.5,
    1.0,
    2.5,
    5.0,
    10.0,
    30.0,
)

# Playback lasts roughly as long as the spoken utterance: a fraction of a
# second for short prompts up to minutes for long read-outs.
PLAYBACK_DURATION_BUCKET_BOUNDARIES_S = (
    0.25,
    0.5,
    1.0,
    2.5,
    5.0,
    10.0,
    20.0,
    30.0,
    60.0,
    120.0,
    300.0,
)

# ---------------------------------------------------------------------------
# Instrument specs
# ---------------------------------------------------------------------------

CALL_DURATION_SPEC = InstrumentSpec(
    name=semconv.METRIC_VOICE_CALL_DURATION,
    kind=InstrumentKind.HISTOGRAM,
    unit="s",
    description=(
        "Seconds from voice-call start to its terminal end. Recorded once "
        "per ended call; its per-outcome counts are also the call-outcome "
        "distribution. Attributes: rasa.voice.outcome (completed for a "
        "normal or agent-requested end, disconnected for a transport-level "
        "drop, failed for an unhandled error)."
    ),
    allowed_attribute_keys=frozenset({semconv.METRIC_ATTR_OUTCOME}),
    bucket_boundaries_s=CALL_DURATION_BUCKET_BOUNDARIES_S,
)

TTS_TIME_TO_FIRST_AUDIO_SPEC = InstrumentSpec(
    name=semconv.METRIC_VOICE_TTS_TIME_TO_FIRST_AUDIO,
    kind=InstrumentKind.HISTOGRAM,
    unit="s",
    description=(
        "Seconds from a speech-synthesis request to its first generated "
        "audio chunk. Recorded once per successfully synthesized agent "
        "utterance; failed syntheses are excluded (see "
        "rasa.voice.operation.failures). Attributes: rasa.voice.provider "
        "(TTS engine name) and rasa.voice.tts.cache_hit (whether the audio "
        "came from the TTS cache)."
    ),
    allowed_attribute_keys=frozenset(
        {
            semconv.METRIC_ATTR_PROVIDER,
            semconv.METRIC_ATTR_TTS_CACHE_HIT,
        }
    ),
    bucket_boundaries_s=TTS_DURATION_BUCKET_BOUNDARIES_S,
)

TTS_SYNTHESIS_DURATION_SPEC = InstrumentSpec(
    name=semconv.METRIC_VOICE_TTS_SYNTHESIS_DURATION,
    kind=InstrumentKind.HISTOGRAM,
    unit="s",
    description=(
        "Seconds from a speech-synthesis request to the utterance's "
        "terminal state. Recorded once per agent utterance that reached a "
        "terminal state. Attributes: rasa.voice.outcome (completed or "
        "error), rasa.voice.provider (TTS engine name), and "
        "rasa.voice.tts.cache_hit (whether the audio came from the TTS "
        "cache)."
    ),
    allowed_attribute_keys=frozenset(
        {
            semconv.METRIC_ATTR_OUTCOME,
            semconv.METRIC_ATTR_PROVIDER,
            semconv.METRIC_ATTR_TTS_CACHE_HIT,
        }
    ),
    bucket_boundaries_s=TTS_DURATION_BUCKET_BOUNDARIES_S,
)

PLAYBACK_DURATION_SPEC = InstrumentSpec(
    name=semconv.METRIC_VOICE_PLAYBACK_DURATION,
    kind=InstrumentKind.HISTOGRAM,
    unit="s",
    description=(
        "Seconds from the first delivered audio chunk of an agent utterance "
        "to its terminal playback state. Recorded once per playback that "
        "delivered at least one chunk. Attributes: rasa.voice.outcome "
        "(completed, interrupted by a user barge-in, cancelled by the "
        "channel, or error)."
    ),
    allowed_attribute_keys=frozenset({semconv.METRIC_ATTR_OUTCOME}),
    bucket_boundaries_s=PLAYBACK_DURATION_BUCKET_BOUNDARIES_S,
)

OPERATION_FAILURES_SPEC = InstrumentSpec(
    name=semconv.METRIC_VOICE_OPERATION_FAILURES,
    kind=InstrumentKind.COUNTER,
    unit="{failure}",
    description=(
        "Unexpected voice operation failures across all pipeline stages. "
        "Counts unhandled exceptions, never expected behavioral outcomes "
        "such as ignored barge-ins or interrupted playback. Attributes: "
        "rasa.voice.component (pipeline stage), rasa.voice.operation "
        "(failing operation), rasa.voice.provider (ASR/TTS engine name, "
        "where applicable), and rasa.voice.error_type (exception class "
        "name, never its message)."
    ),
    allowed_attribute_keys=frozenset(
        {
            semconv.METRIC_ATTR_COMPONENT,
            semconv.METRIC_ATTR_OPERATION,
            semconv.METRIC_ATTR_PROVIDER,
            semconv.METRIC_ATTR_ERROR_TYPE,
        }
    ),
)

BARGE_IN_DECISIONS_SPEC = InstrumentSpec(
    name=semconv.METRIC_VOICE_BARGE_IN_DECISIONS,
    kind=InstrumentKind.COUNTER,
    unit="{decision}",
    description=(
        "Evaluated barge-in decisions: user speech during agent audio that "
        "passed the barge-in gates and was classified. Counted once per "
        "decision. Attributes: rasa.voice.outcome (accepted or ignored) and "
        "rasa.voice.reason (bounded detector reason token)."
    ),
    allowed_attribute_keys=frozenset(
        {
            semconv.METRIC_ATTR_OUTCOME,
            semconv.METRIC_ATTR_REASON,
        }
    ),
)

DTMF_DECISIONS_SPEC = InstrumentSpec(
    name=semconv.METRIC_VOICE_DTMF_DECISIONS,
    kind=InstrumentKind.COUNTER,
    unit="{decision}",
    description=(
        "Evaluated DTMF keypress decisions. Counted once per terminal "
        "decision: a completed digit collection (accepted), a keypress "
        "without an active collect step (ignored), or an abandoned digit "
        "buffer (timeout). Attributes: rasa.voice.outcome (accepted, "
        "ignored, or timeout) and rasa.voice.reason (bounded reason token, "
        "where available)."
    ),
    allowed_attribute_keys=frozenset(
        {
            semconv.METRIC_ATTR_OUTCOME,
            semconv.METRIC_ATTR_REASON,
        }
    ),
)

SILENCE_TIMEOUTS_SPEC = InstrumentSpec(
    name=semconv.METRIC_VOICE_SILENCE_TIMEOUTS,
    kind=InstrumentKind.COUNTER,
    unit="{timeout}",
    description=(
        "Fired user-silence timeouts published as turn events. Counted once "
        "per fired timeout. Attributes: rasa.voice.outcome (accepted) and "
        "rasa.voice.silence.timeout_s (the configured timeout that elapsed, "
        "a configuration value, not a runtime measurement)."
    ),
    allowed_attribute_keys=frozenset(
        {
            semconv.METRIC_ATTR_OUTCOME,
            semconv.METRIC_ATTR_SILENCE_TIMEOUT_S,
        }
    ),
)

AUDIO_BYTES_SPEC = InstrumentSpec(
    name=semconv.METRIC_VOICE_AUDIO_BYTES,
    kind=InstrumentKind.COUNTER,
    unit="By",
    description=(
        "Audio bytes processed during voice calls, accumulated per call and "
        "counted at call end. Attributes: rasa.voice.audio.direction (input "
        "for caller audio, output for agent audio)."
    ),
    allowed_attribute_keys=frozenset({semconv.METRIC_ATTR_AUDIO_DIRECTION}),
)

VOICE_INSTRUMENT_SPECS: Tuple[InstrumentSpec, ...] = (
    CALL_DURATION_SPEC,
    TTS_TIME_TO_FIRST_AUDIO_SPEC,
    TTS_SYNTHESIS_DURATION_SPEC,
    PLAYBACK_DURATION_SPEC,
    OPERATION_FAILURES_SPEC,
    BARGE_IN_DECISIONS_SPEC,
    DTMF_DECISIONS_SPEC,
    SILENCE_TIMEOUTS_SPEC,
    AUDIO_BYTES_SPEC,
)


def voice_metric_views() -> List[View]:
    """Build OpenTelemetry Views for the voice instruments.

    The ``MeterProvider`` created in ``rasa.tracing.metrics_config`` uses
    these views.
    """
    return [spec.to_view() for spec in VOICE_INSTRUMENT_SPECS]


# ---------------------------------------------------------------------------
# Runtime registry (delegates to the shared instrument registry)
# ---------------------------------------------------------------------------


def register_voice_metric_instruments() -> None:
    """Register the voice instruments with the configured SDK provider.

    Called from ``configure_metrics()`` after the meter provider is set.
    If no SDK meter provider is configured, registration is skipped and
    :func:`voice_metrics_enabled` remains false.
    """
    instrument_registry.register_instruments(semconv.METER_NAME, VOICE_INSTRUMENT_SPECS)


def reset_voice_metric_instruments() -> None:
    """Clear the registered instruments (used by tests)."""
    instrument_registry.reset_registered_instruments()


def voice_metrics_enabled() -> bool:
    """Return whether voice metric instruments are registered."""
    return instrument_registry.instruments_registered()


def get_registered_instrument(name: str) -> Optional[Union[Histogram, Counter]]:
    """Return a registered instrument by metric name, if any."""
    return instrument_registry.get_registered_instrument(name)
